from pathlib import Path
import json
root=Path(__file__).parent;data=(root/'explorer-data.json').read_text()
canvas='''import {useHostTheme,useState,H1,H2,Text,Table,LineChart,Grid,Stat} from 'cursor/canvas';
const D=DATA;
const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function score(r:any,mode:string){if(mode==='upside')return .65*r.medianSurplus+.35*r.p90Surplus-.25*r.p90RequiredCash;if(mode==='cash')return .35*r.medianSurplus+.65*r.p10Surplus-r.p90RequiredCash;if(mode==='labs')return .4*r.medianSurplus+.35*r.p10Surplus+.5*r.medianLabs-.75*r.p90RequiredCash;return .6*r.medianSurplus+.4*r.p10Surplus-.75*r.p90RequiredCash+.1*r.medianLabs;}
export default function StrategySimulation(){
 const t=useHostTheme(),[mode,setMode]=useState('balanced'),[selected,setSelected]=useState('06-06'),[capital,setCapital]=useState(0),[family,setFamily]=useState('all'),[page,setPage]=useState(0);
 const ranking=[...D.ranking].sort((a,b)=>score(b,mode)-score(a,mode)),r=D.ranking.find(x=>x.id===selected)!,curve=D.curves[selected as keyof typeof D.curves],requirements=D.funding[selected as keyof typeof D.funding],funded=requirements.filter(v=>v<=capital).length;
 const filtered=ranking.filter(x=>family==='all'||x.family===family),shown=filtered.slice(page*10,page*10+10);
 const selectStyle={background:t.bg.elevated,color:t.text.primary,border:'1px solid '+t.stroke.primary,padding:8,maxWidth:'100%'};
 return <main style={{padding:24,maxWidth:1280,margin:'auto',display:'grid',gap:24,color:t.text.primary,background:t.bg.editor,fontFamily:'system-ui'}}>
 <header><H1>Lunar Paradox: 100 strategies × 100 scenarios</H1><Text>24-month synthetic comparison · USD · 18 October 2026. 10,000 primary runs plus 30,000 holdout/stress comparisons and 10,000 separate bootstrap runs. Inputs are hypotheses, not market evidence or success probabilities.</Text></header>
 <section style={{padding:18,background:t.fill.secondary}}><H2>Best baseline result is conditional</H2><Text>All three leading plans use productized automation. Doubling its assumed delivery effort changes the winner to a specialist AI workflow studio and moves the original #1 to rank 14. Available starting cash is confirmed as zero. No strategy is guaranteed profitable, and none is verified affordable.</Text></section>
 <Grid columns="repeat(auto-fit,minmax(220px,1fr))" gap={18}><Stat label="Confirmed combined baseline / month" value="$12,000"/><Stat label="Distinct commercial models × operating plans" value="10 × 10"/><Stat label="Founder capacity limit / month" value="160 hours"/></Grid>
 <section><H2>With $0 cash: three first-income candidates, not viable winners</H2><Text>Founder confirmed no cash, only existing hardware and skills. A separate 100-offer/plan × 100-scenario bootstrap test found no option covering the $12,000 monthly baseline from zero in all its scheduled payments. These three rank highest within that constrained test, but all have negative median cash after 13 weeks. No new paid staff, tools or advertising are assumed.</Text><Table headers={['Candidate','Illustrative scope price','Median 13-week cash balance','Median bridge funding needed']} rows={D.bootstrap.winners.map(x=>[x.offer+' / '+x.plan,money(x.illustrativePrice),money(x.medianSurplus),money(x.medianFundingNeeded)])}/><Text>These are unvalidated prices, not published offers. Bills assumed due weeks 4, 8, 12; no opening pipeline or repeat contracts assumed. Earlier bills worsen results. Scenario coverage is not a real-world success probability.</Text></section>
 <section><H2>Conditional top three if funded: original 24-month comparison</H2><Table headers={['Strategy','Operating plan','Median surplus / 24 months','10th-percentile surplus','90th-percentile funding need']} rows={D.ranking.slice(0,3).map(x=>[x.id+' · '+x.family,x.plan,money(x.medianSurplus),money(x.p10Surplus),money(x.p90RequiredCash)])}/><Text>Surplus is cash after the combined baseline, incremental delivery costs and modeled Labs spending, before taxes/financing. It is not accounting net profit.</Text></section>
 <section style={{display:'grid',gap:14}}><H2>Explore one strategy</H2><label>Strategy <select aria-label="Strategy" value={selected} onChange={e=>setSelected(e.target.value)} style={selectStyle}>{D.ranking.map(x=><option key={x.id} value={x.id}>{x.id} · {x.family} / {x.plan}</option>)}</select></label>
 <Grid columns="repeat(auto-fit,minmax(210px,1fr))" gap={18}><Stat label="Median 24-month surplus" value={money(r.medianSurplus)}/><Stat label="Median starting funding needed" value={money(r.medianRequiredCash)}/><Stat label="Positive surplus cases / 100 synthetic cases" value={String(r.positiveCases)}/><Stat label="Median Labs spending / 24 months" value={money(r.medianLabs)}/></Grid>
 <label>Illustrative starting cash (not your verified balance): {money(capital)}<input aria-label="Illustrative starting cash" type="range" min="0" max="250000" step="5000" value={capital} onChange={e=>setCapital(Number(e.target.value))} style={{width:'100%',accentColor:t.accent.primary}}/></label><Text>{funded} of 100 designed scenarios fit within that funding amount. This changes the funding comparison only; it does not rerun the business model or estimate a real-world survival probability.</Text>
 <H2>Cumulative free cash from a zero starting balance</H2><Text>Horizontal axis: month 1–24. Vertical axis: USD. Negative values indicate external cash required; unearned client deposits are excluded.</Text><LineChart categories={Array.from({length:24},(_,i)=>String(i+1))} series={[{name:'10th scenario percentile',data:curve['0.1']},{name:'Median scenario',data:curve['0.5']},{name:'90th scenario percentile',data:curve['0.9']}]} height={300} beginAtZero={false} referenceLines={[{value:0,label:'Zero free cash'}]} valuePrefix="$"/><Text>Source: simulate.py, seed 20261018, 100 synthetic scenarios per strategy. Pointwise scenario percentiles are descriptive, not confidence bands or one continuous realized path.</Text>
 </section>
 <section style={{display:'grid',gap:14}}><H2>All 100 ways to operate</H2><div style={{display:'flex',gap:18,flexWrap:'wrap'}}><label>Ranking priority <select value={mode} onChange={e=>{setMode(e.target.value);setPage(0)}} style={selectStyle}><option value="balanced">Balanced</option><option value="cash">Cash/downside first</option><option value="upside">Upside first</option><option value="labs">Labs funding</option></select></label><label>Commercial model <select value={family} onChange={e=>{setFamily(e.target.value);setPage(0)}} style={selectStyle}><option value="all">All models</option>{D.families.map(x=><option key={x[0]} value={x[0]}>{x[0]}</option>)}</select></label></div>
 <Table headers={['ID / model','Operating plan','Median surplus','Funding need p90','Positive cases / 100']} rows={shown.map(x=>[<button key={x.id} onClick={()=>setSelected(x.id)} style={{background:'none',border:0,color:t.text.link,cursor:'pointer',textAlign:'left'}}>{x.id} · {x.family}</button>,x.plan,money(x.medianSurplus),money(x.p90RequiredCash),String(x.positiveCases)])}/><div style={{display:'flex',gap:14}}><button disabled={page===0} onClick={()=>setPage(page-1)} style={selectStyle}>Previous</button><Text>Rows {page*10+1}–{Math.min(filtered.length,page*10+10)} / {filtered.length}</Text><button disabled={(page+1)*10>=filtered.length} onClick={()=>setPage(page+1)} style={selectStyle}>Next</button></div>
 </section>
 <section><H2>What must be validated before choosing</H2><Text>Real buyer willingness to pay; qualified leads and close rates; delivery and support hours; contractor rates and availability; actual baseline expenses and tax treatment; starting cash. The model assumes enough funding to finish commitments and does not model insolvency shutdown or fundraising. No company website offers or prices were published.</Text><Text>Primary score = 0.60 median surplus + 0.40 p10 surplus − 0.75 p90 funding need + 0.10 median Labs spending. These are judgement weights. The current $12,000 includes living withdrawals, so these outputs must not be treated as corporate net profit.</Text></section>
 </main>;
}
'''.replace('const D=DATA;','const D='+data+';')
(root/'strategy-explorer.canvas.tsx').write_text(canvas)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lunar Paradox — strategy simulation</title><style>body{font:15px/1.6 system-ui;margin:0;background:#f5f5f3;color:#20211f}main{max-width:1180px;margin:auto;padding:30px}h1{font-size:24px}h2{font-size:19px;margin-top:32px}.note{background:#e7e9e3;padding:18px}select,input,button{font:inherit;padding:8px;max-width:100%}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:12px;border-bottom:1px solid #ccc;text-align:left}th{background:#e9e9e6}.table{overflow:auto}.stats{display:flex;gap:30px;flex-wrap:wrap;margin:20px 0}.stats strong{display:block;font-size:21px}.controls{display:flex;gap:20px;flex-wrap:wrap}.chart{background:#fff;padding:15px}svg{width:100%;height:auto}small{color:#555}a,button{color:#244928}button{cursor:pointer}button:disabled{opacity:.5}.pill{font-size:12px}footer{margin-top:35px}</style><main><h1>Lunar Paradox: 100 ways to operate × 100 scenarios</h1><p>24 months · USD · 18 October 2026 · 10,000 primary comparisons + 30,000 checks + 10,000 bootstrap comparisons.</p><div class="note"><strong>Decision model, not a forecast.</strong> Every commercial input is an unvalidated hypothesis. These are synthetic scenario counts, not success probabilities. All three leading baseline plans use productized automation; when its assumed delivery effort doubles, the winner becomes a specialist AI workflow studio. Starting cash is confirmed as zero.</div><h2>With $0 cash: first-income candidates, not viable winners</h2><p>The separate 13-week bootstrap model tests 100 offer/operating combinations × 100 scenarios. None covers all modeled bills from zero cash in this test set. Highest-ranked first-income paths are shown below; none is proven viable at the current $12,000 monthly baseline.</p><div class="table"><table><thead><tr><th>First-income candidate</th><th>Illustrative scope price</th><th>Median 13-week cash balance</th><th>Median bridge funding needed</th></tr></thead><tbody id="bootstrap"></tbody></table></div><p>Prices are unvalidated assumptions, not published offers. No paid advertising, contractors, hires or new subscriptions. Bills favorably assumed at weeks 4/8/12; no existing pipeline or repeat contracts assumed.</p><h2>Conditional top three if funded: 24-month comparison</h2><div class="table"><table><thead><tr><th>Strategy</th><th>Median 24-month surplus</th><th>10th-percentile surplus</th><th>90th-percentile funding needed</th></tr></thead><tbody id="top"></tbody></table></div><p>Surplus is after the $12,000/month combined company/living baseline, incremental delivery costs and modeled Labs spending. It excludes taxes and financing and is <strong>not accounting net profit</strong>.</p><h2>Inspect a strategy</h2><label>Strategy <select id="strategy"></select></label><div id="metrics" class="stats"></div><label>Illustrative starting cash: <strong id="cash-label"></strong><input id="cash" type="range" min="0" max="250000" step="5000" value="0" style="width:100%"></label><p id="coverage"></p><h2>Cumulative free cash from zero starting balance</h2><div id="chart" class="chart"></div><small>Source: simulate.py · primary seed 20261018 · 100 designed scenarios per strategy · pointwise percentiles, not confidence intervals or a single realized path.</small><h2>All 100 operating strategies</h2><div class="controls"><label>Ranking priority <select id="mode"><option value="balanced">Balanced</option><option value="cash">Cash/downside first</option><option value="upside">Upside first</option><option value="labs">Labs funding</option></select></label><label>Commercial model <select id="family"><option value="all">All commercial models</option></select></label></div><div class="table"><table><thead><tr><th>Strategy</th><th>Operating plan</th><th>Median surplus</th><th>Funding need p90</th><th>Positive cases / 100</th></tr></thead><tbody id="rows"></tbody></table></div><p id="range"></p><button id="prev">Previous</button> <button id="next">Next</button><h2>Critical limitations</h2><p>Founder limited to 160 hours/month, including sales, supervision and R&D. Interns are not assumed to be free senior delivery capacity. Clients, accepted prices, conversion rates, effort and starting cash are unverified. Required funding assumes access to enough cash to finish commitments; the model does not simulate bankruptcy or raising investment. No actual website pricing was changed.</p><p>Balanced score: 0.60 × median surplus + 0.40 × p10 surplus − 0.75 × p90 funding need + 0.10 × median Labs spending. Weights express judgement. Alternate ranking priorities show how the decision changes.</p><p>These are 10 commercial models crossed with 10 operating plans—not 100 independently validated market opportunities.</p><footer><a href="../REPORT.md">Full assumptions and conclusions</a> · <a href="../strategies.csv">All 100 strategies CSV</a> · <a href="../all-runs.csv">10,000 primary outcomes CSV</a> · <a href="../bootstrap-strategies.csv">100 bootstrap options CSV</a></footer></main><script>const D=DATA;
const $=s=>document.getElementById(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let page=0;
function score(r,m){if(m==='upside')return .65*r.medianSurplus+.35*r.p90Surplus-.25*r.p90RequiredCash;if(m==='cash')return .35*r.medianSurplus+.65*r.p10Surplus-r.p90RequiredCash;if(m==='labs')return .4*r.medianSurplus+.35*r.p10Surplus+.5*r.medianLabs-.75*r.p90RequiredCash;return .6*r.medianSurplus+.4*r.p10Surplus-.75*r.p90RequiredCash+.1*r.medianLabs;}
$('bootstrap').innerHTML=D.bootstrap.winners.map(r=>`<tr><td>${r.offer} / ${r.plan}</td><td>${money(r.illustrativePrice)}</td><td>${money(r.medianSurplus)}</td><td>${money(r.medianFundingNeeded)}</td></tr>`).join('');$('top').innerHTML=D.ranking.slice(0,3).map(r=>`<tr><td>${r.id} · ${r.family}<br>${r.plan}</td><td>${money(r.medianSurplus)}</td><td>${money(r.p10Surplus)}</td><td>${money(r.p90RequiredCash)}</td></tr>`).join('');$('strategy').innerHTML=D.ranking.map(r=>`<option value="${r.id}">${r.id} · ${r.family} / ${r.plan}</option>`).join('');$('family').innerHTML+=D.families.map(f=>`<option>${f[0]}</option>`).join('');
function detail(){const id=$('strategy').value,r=D.ranking.find(x=>x.id===id),cash=Number($('cash').value);$('cash-label').textContent=money(cash);$('metrics').innerHTML=`<div>Median surplus / 24 months<strong>${money(r.medianSurplus)}</strong></div><div>Median funding required<strong>${money(r.medianRequiredCash)}</strong></div><div>Median Labs spending / 24 months<strong>${money(r.medianLabs)}</strong></div>`;$('coverage').textContent=`${D.funding[id].filter(x=>x<=cash).length} of 100 designed scenarios fit that illustrative funding amount. This is not a survival probability.`;const c=D.curves[id],all=Object.values(c).flat(),lo=Math.min(0,...all),hi=Math.max(0,...all),span=Math.max(1,hi-lo),x=i=>70+i/23*790,y=v=>280-(v-lo)/span*220;let grid='';for(let i=0;i<5;i++){const v=lo+i/4*span;grid+=`<line x1="70" x2="860" y1="${y(v)}" y2="${y(v)}" stroke="#ddd"/><text x="65" y="${y(v)+4}" text-anchor="end" font-size="11">${Math.round(v/1000)}k</text>`;}const paths=[['0.1','10th scenario percentile','5 5'],['0.5','Median scenario',''],['0.9','90th scenario percentile','2 4']].map(([k,label,dash])=>`<polyline fill="none" stroke="${k==='0.5'?'#244928':'#777'}" stroke-width="${k==='0.5'?3:1.5}" stroke-dasharray="${dash}" points="${c[k].map((v,i)=>x(i)+','+y(v)).join(' ')}"/>`).join('');$('chart').innerHTML=`<p>Vertical axis: free cash (USD thousands). Horizontal axis: month 1–24.</p><svg viewBox="0 0 900 325" role="img" aria-label="Scenario percentile cash curves"><text x="15" y="35" font-size="12">USD k</text>${grid}<line x1="70" x2="860" y1="${y(0)}" y2="${y(0)}" stroke="#222"/>${paths}${[0,5,11,17,23].map(i=>`<text x="${x(i)}" y="304" text-anchor="middle" font-size="12">${i+1}</text>`).join('')}<text x="465" y="324" text-anchor="middle" font-size="12">Month</text></svg><p class="pill">Dashed: 10th percentile · Solid green: median · Dotted: 90th percentile</p>`;}
function rows(){const list=[...D.ranking].sort((a,b)=>score(b,$('mode').value)-score(a,$('mode').value)).filter(r=>$('family').value==='all'||r.family===$('family').value);page=Math.min(page,Math.max(0,Math.ceil(list.length/10)-1));$('rows').innerHTML=list.slice(page*10,page*10+10).map(r=>`<tr><td><button data-id="${r.id}">${r.id} · ${r.family}</button></td><td>${r.plan}</td><td>${money(r.medianSurplus)}</td><td>${money(r.p90RequiredCash)}</td><td>${r.positiveCases}</td></tr>`).join('');$('range').textContent=`Rows ${page*10+1}–${Math.min(list.length,page*10+10)} of ${list.length}`;$('prev').disabled=page===0;$('next').disabled=(page+1)*10>=list.length;}
$('strategy').onchange=detail;$('cash').oninput=detail;for(const id of ['mode','family'])$(id).onchange=()=>{page=0;rows()};$('prev').onclick=()=>{page--;rows()};$('next').onclick=()=>{page++;rows()};$('rows').onclick=e=>{const b=e.target.closest('[data-id]');if(b){$('strategy').value=b.dataset.id;detail();$('strategy').scrollIntoView({block:'center'});}};detail();rows();
</script></html>'''.replace('const D=DATA;','const D='+data+';')
(root/'report').mkdir(exist_ok=True);(root/'report/index.html').write_text(html)
